p=[[2,3,3,6,7],[0,4,4,2,2],[2,6,0,4,3],[3,7,7,6,3],[3,3,2,3,3]]
markers=[(4,19),(5,13),(9,20),(13,7),(14,17)]
g=[[3]*23 for _ in range(17)]
for r in range(5,10):
 for c in range(5,10): g[r][c]=p[r-5][c-5]
for cr,cc in markers:
 for i in range(5):
  for j in range(5):
   rr,co=cr+i-2,cc+j-2
   if 0<=rr<17 and 0<=co<23 and p[i][j]!=3:
    g[rr][co]=p[i][j]
print('\n'.join(' '.join(map(str,row)) for row in g))
